{
  "metadata": {
    "run_id": "cw-ms-remote-0a1b2c3d",
    "review_date": "2026-10-28",
    "last_updated": "2026-10-28T21:12:08.882345+00:00"
  },
  "company_name": "Cadence",
  "slug": "cadence",
  "stage": "seed",
  "sector": "B2B SaaS",
  "geography": "US",
  "sector_type": "saas"
}

{
  "items": [
    {
      "id": "structural_tam_gt_sam_gt_som",
      "category": "Structural Checks",
      "label": "TAM > SAM > SOM",
      "status": "pass",
      "notes": "Both approaches satisfy the hierarchy. Top-down: TAM $2.1B > SAM $323M > SOM $9.7M. Bottom-up: TAM $464M > SAM $427M > SOM $10.7M. No inversions in either build."
    },
    {
      "id": "structural_definitions_correct",
      "category": "Structural Checks",
      "label": "Definitions used correctly",
      "status": "pass",
      "notes": "TAM is the total US field-service management software market (top-down) or all target-trade establishments at full ARPU (bottom-up). SAM is narrowed to the HVAC/plumbing/electrical SMB segment by size filter and segment share. SOM is the obtainable 3-year capture share. All three definitions are applied correctly."
    },
    {
      "id": "tam_matches_product_scope",
      "category": "TAM Scoping",
      "label": "TAM matches product scope",
      "status": "pass",
      "notes": "The top-down build uses the full US FSM software market as TAM and narrows to the HVAC/plumbing/electrical SMB segment at SAM, which is the appropriate layering for a top-down approach. The bottom-up TAM is built directly from the target establishment counts. The large gap between the two TAMs (factor of 4.5) reflects that the top-down TAM covers all field-service trades, not just the three targeted \u2014 an acknowledged limitation, not a scope error."
    },
    {
      "id": "source_segments_match",
      "category": "TAM Scoping",
      "label": "Source segments match product segments",
      "status": "pass",
      "notes": "The US FSM market total sources are tagged as broad segment match and cover all field-service trades; this mismatch is explicitly acknowledged and the HVAC/plumbing/electrical narrowing is flagged as an agent estimate. The bottom-up establishment counts (NAICS 238220 and 23821) exactly match the target trades. The SMB size filter uses Census size-distribution data for the same NAICS codes. The segment-source mismatch at the TAM layer is disclosed rather than hidden."
    },
    {
      "id": "som_share_defensible",
      "category": "SOM Realism",
